def _esc(value):
    return (str(value).replace("&", "&amp;").replace("<", "&lt;")
            .replace(">", "&gt;").replace('"', "&quot;"))


def render(text, x, y, size=10, color="#1f2431", anchor="middle"):
    """Return a path-only SVG group for a known Hindi label."""
    item = LABELS.get(str(text))
    if item is None:
        raise KeyError(f"no pre-shaped Hindi SVG label for {text!r}")
    scale = float(size) / FONT_UNITS
    total = item["advance"] * scale
    if anchor == "middle":
        start = float(x) - total / 2
    elif anchor == "end":
        start = float(x) - total
    else:
        start = float(x)
    parts = [f'<g fill="{_esc(color)}">']
    cursor = start
    for glyph in item["glyphs"]:
        gx = cursor + glyph["x"] * scale
        gy = float(y) + glyph["y"] * scale
        if glyph["d"]:
            parts.append(
                f'<path d="{glyph["d"]}" transform="translate({gx:.3f},{gy:.3f}) '
                f'scale({scale:.8f},{-scale:.8f})"/>')
        cursor += glyph["advance"] * scale
    parts.append('</g>')
    return "".join(parts)


def available():
    return sorted(LABELS)
